CREATE TABLE IF NOT EXISTS nicar."Financiera" (
  "IdFinanciera" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(150) NOT NULL UNIQUE,
  "SitioWeb" varchar(250),
  "InstruccionesPago" varchar(500),
  "Observaciones" varchar(500),
  "PlazoMinimoMeses" smallint NOT NULL DEFAULT 1 CHECK ("PlazoMinimoMeses">=1),
  "PlazoMaximoMeses" smallint NOT NULL DEFAULT 84 CHECK ("PlazoMaximoMeses" BETWEEN "PlazoMinimoMeses" AND 84),
  "Activo" boolean NOT NULL DEFAULT true
);

INSERT INTO nicar."Financiera" ("Nombre","SitioWeb","Observaciones","PlazoMinimoMeses","PlazoMaximoMeses")
VALUES ('CREDEX','https://www.credex.com.ni/','Financiamiento externo. Registrar únicamente las condiciones confirmadas por FID/CREDEX; verificar vigencia y aceptación de la unidad.','3','36')
ON CONFLICT ("Nombre") DO UPDATE SET "PlazoMinimoMeses"=EXCLUDED."PlazoMinimoMeses",
  "PlazoMaximoMeses"=EXCLUDED."PlazoMaximoMeses";

CREATE TABLE IF NOT EXISTS nicar."Credito" (
  "IdCredito" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdVenta" integer NOT NULL UNIQUE REFERENCES nicar."Venta"("IdVenta"),
  "IdFinanciera" integer NOT NULL REFERENCES nicar."Financiera"("IdFinanciera"),
  "NumeroContrato" varchar(100) NOT NULL,
  "PrecioContadoUSD" numeric(12,2) NOT NULL CHECK ("PrecioContadoUSD">0),
  "PrimaUSD" numeric(12,2) NOT NULL CHECK ("PrimaUSD">=0),
  "CargosFinancierosUSD" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("CargosFinancierosUSD">=0),
  "MontoFinanciadoUSD" numeric(12,2) NOT NULL CHECK ("MontoFinanciadoUSD">0),
  "TasaAnual" numeric(7,4) NOT NULL CHECK ("TasaAnual">=0 AND "TasaAnual"<=100),
  "TasaMoraAnual" numeric(7,4) NOT NULL CHECK ("TasaMoraAnual">=0 AND "TasaMoraAnual"<=100),
  "PlazoMeses" smallint NOT NULL CHECK ("PlazoMeses" BETWEEN 1 AND 84),
  "PagoMensualUSD" numeric(12,2) NOT NULL CHECK ("PagoMensualUSD">0),
  "TotalInteresesUSD" numeric(12,2) NOT NULL CHECK ("TotalInteresesUSD">=0),
  "TotalContratoUSD" numeric(12,2) NOT NULL CHECK ("TotalContratoUSD">0),
  "FechaPrimerPago" date NOT NULL,
  "Estado" varchar(20) NOT NULL DEFAULT 'Activo' CHECK ("Estado" IN ('Activo','Pagado','Cancelado')),
  "FechaRegistro" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS nicar."PagoCredito" (
  "IdPagoCredito" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IdCredito" integer NOT NULL REFERENCES nicar."Credito"("IdCredito"),
  "NumeroCuota" smallint CHECK ("NumeroCuota">0),
  "IdUsuario" integer NOT NULL REFERENCES nicar."Usuario"("IdUsuario"),
  "FechaPago" date NOT NULL,
  "MontoUSD" numeric(12,2) NOT NULL CHECK ("MontoUSD">0),
  "Referencia" varchar(100) NOT NULL,
  "Estado" varchar(20) NOT NULL DEFAULT 'PendienteRevision' CHECK ("Estado" IN ('PendienteRevision','Aprobado','Rechazado')),
  "RevisadoPor" integer REFERENCES nicar."Usuario"("IdUsuario"),
  "FechaRevision" timestamptz,
  "Observaciones" varchar(300)
);

CREATE INDEX IF NOT EXISTS "PagoCredito_Revision_idx"
  ON nicar."PagoCredito"("Estado","FechaPago");

REVOKE ALL ON nicar."Financiera", nicar."Credito", nicar."PagoCredito"
  FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON nicar."Financiera", nicar."Credito", nicar."PagoCredito" TO postgres;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA nicar TO postgres;
